  "Every record you view, edit, override or export is written to an append-only audit log with your name.": "ଆପଣ ଦେଖିଥିବା, ବଦଳାଇଥିବା, ଓଭରରାଇଡ୍ କିମ୍ବା ଏକ୍ସପୋର୍ଟ କରିଥିବା ପ୍ରତି ରେକର୍ଡ ଆପଣଙ୍କ ନାମ ସହ ଅଡିଟ୍ ଲଗ୍‌ରେ ଲେଖାହୁଏ।",
