  "Find a returning patient or register a new one, then take them through the check-in kiosk for a token.": "ଫେରି ଆସିଥିବା ରୋଗୀଙ୍କୁ ଖୋଜନ୍ତୁ କିମ୍ବା ନୂଆ ପଞ୍ଜୀକରଣ କରନ୍ତୁ, ତା’ପରେ ଟୋକେନ୍ ପାଇଁ ଚେକ୍-ଇନ୍ କିଓସ୍କରେ ନିଅନ୍ତୁ।",
