  "Fitness": "ଫିଟନେସ୍",
  "Fitness status by department. This view never contains symptoms, diagnoses, notes or reports.": "ବିଭାଗ ଅନୁସାରେ ଫିଟନେସ୍ ସ୍ଥିତି। ଏଥିରେ କେବେ ଲକ୍ଷଣ, ନିଦାନ, ନୋଟ୍ କିମ୍ବା ରିପୋର୍ଟ ରହେ ନାହିଁ।",
  "Fix registration mistakes. Clinical notes are not changed here.": "ପଞ୍ଜୀକରଣ ଭୁଲ ସଂଶୋଧନ କରନ୍ତୁ। କ୍ଲିନିକାଲ୍ ନୋଟ୍ ଏଠାରେ ବଦଳେ ନାହିଁ।",
