  "For your security, only your facility supervisor can reset a doctor, nurse or receptionist PIN. Ask them to open Admin → Staff → Reset PIN, then sign in again to create a new one.": "ଆପଣଙ୍କ ସୁରକ୍ଷା ପାଇଁ ଡାକ୍ତର, ନର୍ସ କିମ୍ବା ରିସେପସନିଷ୍ଟଙ୍କ ପିନ୍ କେବଳ କେନ୍ଦ୍ର ସୁପରଭାଇଜର ରିସେଟ୍ କରିପାରିବେ। ସେମାନଙ୍କୁ Admin → Staff → Reset PIN କରିବାକୁ କୁହନ୍ତୁ, ତା’ପରେ ପୁଣି ସାଇନ୍ ଇନ୍ କରି ନୂଆ ପିନ୍ ତିଆରି କରନ୍ତୁ।",
