  "From the append-only audit log": "କେବଳ-ଯୋଡ଼ିହେବା ଅଡିଟ୍ ଲଗ୍‌ରୁ",
  "Front desk": "ଫ୍ରଣ୍ଟ ଡେସ୍କ",
