  "Full specialist suite; escalation mostly within the facility.": "ସମସ୍ତ ବିଶେଷଜ୍ଞ ଉପଲବ୍ଧ; ଅଧିକାଂଶ ଏସ୍କାଲେସନ୍ କେନ୍ଦ୍ର ଭିତରେ।",
