  "Give each waiting area its own kiosk link or QR poster. Check-ins show up in the tokens list instantly.": "ପ୍ରତି ଅପେକ୍ଷା ସ୍ଥାନକୁ ନିଜର କିଓସ୍କ ଲିଙ୍କ କିମ୍ବା QR ପୋଷ୍ଟର ଦିଅନ୍ତୁ। ଚେକ୍-ଇନ୍ ତୁରନ୍ତ ଟୋକେନ୍ ତାଲିକାରେ ଦେଖାଯାଏ।",
  "Give the link a name, e.g. 'OPD waiting area'": "ଲିଙ୍କକୁ ନାମ ଦିଅନ୍ତୁ, ଯେପରି 'OPD ଅପେକ୍ଷା କକ୍ଷ'",
  "Give the slip to the patient or send it with the referral. Share the code separately if you send the link by message.": "ସ୍ଲିପ୍ ରୋଗୀଙ୍କୁ ଦିଅନ୍ତୁ କିମ୍ବା ରେଫରାଲ୍ ସହ ପଠାନ୍ତୁ। ଲିଙ୍କ ମେସେଜ୍‌ରେ ପଠାଇଲେ କୋଡ୍ ଅଲଗା ଭାବେ ଦିଅନ୍ତୁ।",
  "Glucose (POC)": "ଗ୍ଲୁକୋଜ୍ (POC)",
  "Government and private health facilities across India are listed (© OpenStreetMap contributors, ODbL). Company clinics, industrial units, campus health centres and health camps appear once their organisation registers on Jeevia.": "ଭାରତର ସରକାରୀ ଓ ଘରୋଇ ସ୍ୱାସ୍ଥ୍ୟ କେନ୍ଦ୍ର ତାଲିକାଭୁକ୍ତ (© OpenStreetMap ଯୋଗଦାନକାରୀ, ODbL)। କମ୍ପାନୀ କ୍ଲିନିକ୍, ଶିଳ୍ପ ୟୁନିଟ୍, କ୍ୟାମ୍ପସ୍ ସ୍ୱାସ୍ଥ୍ୟ କେନ୍ଦ୍ର ଓ ସ୍ୱାସ୍ଥ୍ୟ ଶିବିର ସଂସ୍ଥା Jeevia ରେ ପଞ୍ଜୀକରଣ କଲା ପରେ ଦେଖାଯାଏ।",
  "Government programme": "ସରକାରୀ କାର୍ଯ୍ୟକ୍ରମ",
