  "Health centres run by your organisation. Each one appears in Jeevia’s workplace search so doctors and nurses can join it.": "ଆପଣଙ୍କ ସଂସ୍ଥା ଦ୍ୱାରା ପରିଚାଳିତ ସ୍ୱାସ୍ଥ୍ୟ କେନ୍ଦ୍ର। ପ୍ରତ୍ୟେକ Jeevia ର କାର୍ଯ୍ୟସ୍ଥଳ ଖୋଜାରେ ଦେଖାଯାଏ ଯାହାଦ୍ୱାରା ଡାକ୍ତର ଓ ନର୍ସ ଯୋଗଦେଇପାରିବେ।",
  "Helper's name": "ସହାୟକଙ୍କ ନାମ",
  "Hide PIN": "ପିନ୍ ଲୁଚାନ୍ତୁ",
  "Highlighted box = pixels the value was read from. Values that disagree between engines are marked “needs checking”.": "ହାଇଲାଇଟ୍ ବକ୍ସ = ଯେଉଁ ପିକ୍ସେଲରୁ ମୂଲ୍ୟ ପଢ଼ାଗଲା। ଇଞ୍ଜିନ୍ ମଧ୍ୟରେ ଅସହମତ ମୂଲ୍ୟ “ଯାଞ୍ଚ ଆବଶ୍ୟକ” ଭାବେ ଚିହ୍ନିତ।",
  "History from": "ଇତିହାସ",
