  "Icon mode": "ଛବି ମୋଡ୍",
  "Illness": "ଅସୁସ୍ଥତା",
  "Image": "ଛବି",
  "Immediate": "ତୁରନ୍ତ",
  "Import": "ଆମଦାନି କରନ୍ତୁ",
