  "Increases all text and touch targets.": "ସମସ୍ତ ଅକ୍ଷର ଓ ବଟନ୍ ବଡ଼ କରେ।",
  "Industrial Estate Health Unit": "ଶିଳ୍ପାଞ୍ଚଳ ସ୍ୱାସ୍ଥ୍ୟ ୟୁନିଟ୍",
  "Industrial estate / unit": "ଶିଳ୍ପାଞ୍ଚଳ / ୟୁନିଟ୍",
  "Industrial unit health centre": "ଶିଳ୍ପ ୟୁନିଟ୍ ସ୍ୱାସ୍ଥ୍ୟ କେନ୍ଦ୍ର",
  "Insert example rows": "ଉଦାହରଣ ଧାଡ଼ି ଯୋଡ଼ନ୍ତୁ",
  "Intakes are queued in IndexedDB on this device and synced automatically when you switch back online.": "ଇନଟେକ୍ ଏହି ଡିଭାଇସରେ ସୁରକ୍ଷିତ ରହେ ଏବଂ ଅନଲାଇନ୍ ହେବା ମାତ୍ରେ ଆପେ ପଠାହୁଏ।",
  "Intakes captured offline keep their original capture time, so waiting time is never understated.": "ଅଫଲାଇନରେ ଲେଖାଯାଇଥିବା ଇନଟେକ୍ ମୂଳ ସମୟ ରଖେ, ତେଣୁ ଅପେକ୍ଷା ସମୟ କେବେ କମ୍ ଦେଖାଯାଏ ନାହିଁ।",
