  "Once registered, your doctors, nurses and workers can pick this workplace when they sign up. Add more sites later from the employer portal.": "ପଞ୍ଜୀକରଣ ପରେ ଆପଣଙ୍କ ଡାକ୍ତର, ନର୍ସ ଓ କର୍ମଚାରୀ ସାଇନ୍ ଅପ୍ ସମୟରେ ଏହି କାର୍ଯ୍ୟସ୍ଥଳ ବାଛିପାରିବେ। ପରେ ନିଯୁକ୍ତିଦାତା ପୋର୍ଟାଲରୁ ଅଧିକ କେନ୍ଦ୍ର ଯୋଡ଼ନ୍ତୁ।",
  "Online": "ଅନଲାଇନ୍",
  "Only bound devices can run patient intake. Revoking a lost tablet stops it immediately.": "କେବଳ ବାଇଣ୍ଡ ହୋଇଥିବା ଡିଭାଇସ୍ ରୋଗୀ ଇନଟେକ୍ ଚଳାଇପାରେ। ହଜିଯାଇଥିବା ଟାବଲେଟ୍ ବାତିଲ୍ କଲେ ତାହା ତୁରନ୍ତ ବନ୍ଦ ହୁଏ।",
  "Open": "ଖୋଲନ୍ତୁ",
  "Open a case and choose “Referral note” to prepare one.": "କେସ୍ ଖୋଲି ପ୍ରସ୍ତୁତ କରିବା ପାଇଁ “ରେଫରାଲ୍ ନୋଟ୍” ବାଛନ୍ତୁ।",
  "Open case": "କେସ୍ ଖୋଲନ୍ତୁ",
