  "Opening kiosk…": "କିଓସ୍କ ଖୋଲୁଛି…",
  "Operational view. Counts only — facility admins cannot open clinical notes.": "ପରିଚାଳନା ଦୃଶ୍ୟ। କେବଳ ସଂଖ୍ୟା — କେନ୍ଦ୍ର ଆଡମିନ୍ କ୍ଲିନିକାଲ୍ ନୋଟ୍ ଖୋଲିପାରିବେ ନାହିଁ।",
  "Optional. Entered by the nurse / ANM. Readings feed the deterministic rules engine.": "ଇଚ୍ଛାଧୀନ। ନର୍ସ / ANM ଦ୍ୱାରା ଲେଖା। ପଠନ ସ୍ଥିର ନିୟମ ଇଞ୍ଜିନକୁ ଯାଏ।",
