  "Patient summary shared by": "ରୋଗୀ ସାରାଂଶ ଦେଇଛନ୍ତି",
  "Patients do not sign in. A nurse, ANM or receptionist unlocks this tablet with their staff account; it then stays in intake mode.": "ରୋଗୀ ସାଇନ୍ ଇନ୍ କରନ୍ତି ନାହିଁ। ନର୍ସ, ANM କିମ୍ବା ରିସେପସନିଷ୍ଟ ନିଜ କର୍ମଚାରୀ ଖାତାରେ ଏହି ଟାବଲେଟ୍ ଖୋଲନ୍ତି; ତା’ପରେ ଏହା ଇନଟେକ୍ ମୋଡରେ ରହେ।",
