  "Phone verified. Enter your 4–6 digit account PIN to open your dashboard.": "ଫୋନ୍ ଯାଞ୍ଚ ହେଲା। ଡ୍ୟାସବୋର୍ଡ ଖୋଲିବାକୁ ଆପଣଙ୍କ 4–6 ଅଙ୍କର ଖାତା ପିନ୍ ଦିଅନ୍ତୁ।",
  "Phone verified. This number is new — please register.": "ଫୋନ୍ ଯାଞ୍ଚ ହେଲା। ଏହି ନମ୍ବର ନୂଆ — ଦୟାକରି ପଞ୍ଜୀକରଣ କରନ୍ତୁ।",
  "Phones are often shared within a household — confirm identity before opening a record.": "ଘରେ ଫୋନ୍ ଅନେକ ସମୟରେ ବାଣ୍ଟି ହୁଏ — ରେକର୍ଡ ଖୋଲିବା ପୂର୍ବରୁ ପରିଚୟ ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "Photo of the problem": "ସମସ୍ୟାର ଫଟୋ",
  "Photos and reports are deleted automatically after 3–7 days. Voice recordings after 24 hours.": "ଫଟୋ ଓ ରିପୋର୍ଟ 3–7 ଦିନ ପରେ ଆପେ ବିଲୋପ ହୁଏ। ସ୍ୱର ରେକର୍ଡିଂ 24 ଘଣ୍ଟା ପରେ।",
