  "Point the camera at the patient's token QR": "କ୍ୟାମେରାକୁ ରୋଗୀଙ୍କ ଟୋକେନ୍ QR ଆଡ଼କୁ କରନ୍ତୁ",
  "Preferred language": "ପସନ୍ଦର ଭାଷା",
