  "Pregnancy details": "ଗର୍ଭାବସ୍ଥା ବିବରଣୀ",
  "Prepared from the triage note and this facility's specialist configuration. Review before sending.": "ଟ୍ରାଏଜ୍ ନୋଟ୍ ଓ ଏହି କେନ୍ଦ୍ରର ବିଶେଷଜ୍ଞ ବିନ୍ୟାସରୁ ପ୍ରସ୍ତୁତ। ପଠାଇବା ପୂର୍ବରୁ ସମୀକ୍ଷା କରନ୍ତୁ।",
  "Primary Health Centre": "ପ୍ରାଥମିକ ସ୍ୱାସ୍ଥ୍ୟ କେନ୍ଦ୍ର",
