  "Raw voice recordings and photos are deleted automatically after the retention window.": "କଞ୍ଚା ସ୍ୱର ରେକର୍ଡିଂ ଓ ଫଟୋ ସଂରକ୍ଷଣ ଅବଧି ପରେ ଆପେ ବିଲୋପ ହୁଏ।",
