  "Record vitals and bedside observations. The doctor sees them in the case straight away.": "ଭାଇଟାଲ୍ ଓ ଶଯ୍ୟା ପାଖ ପର୍ଯ୍ୟବେକ୍ଷଣ ଲେଖନ୍ତୁ। ଡାକ୍ତର ତୁରନ୍ତ କେସରେ ଦେଖନ୍ତି।",
  "Recorded by nurses and doctors during this visit": "ଏହି ଭିଜିଟ୍‌ରେ ନର୍ସ ଓ ଡାକ୍ତରଙ୍କ ଦ୍ୱାରା ଲେଖା",
