  "You only see what your role needs. Patient documents and photos open only for the doctors and nurses treating that patient. Employers see fitness status only.": "ଆପଣ କେବଳ ଆପଣଙ୍କ ଭୂମିକା ପାଇଁ ଆବଶ୍ୟକ ଜିନିଷ ଦେଖନ୍ତି। ରୋଗୀଙ୍କ ଦସ୍ତାବିଜ ଓ ଫଟୋ କେବଳ ଚିକିତ୍ସା କରୁଥିବା ଡାକ୍ତର ଓ ନର୍ସ ଖୋଲିପାରନ୍ତି। ନିଯୁକ୍ତିଦାତା କେବଳ ଫିଟନେସ୍ ସ୍ଥିତି ଦେଖନ୍ତି।",
  "Your PIN is 4–6 digits": "ଆପଣଙ୍କ ପିନ୍ 4–6 ଅଙ୍କର",
  "Your PIN is the second factor after the phone OTP.": "ଆପଣଙ୍କ ପିନ୍ ଫୋନ୍ OTP ପରେ ଦ୍ୱିତୀୟ ସୁରକ୍ଷା ପର୍ଯ୍ୟାୟ।",
  "Your dashboard is protected by two factors: your phone OTP and a PIN only you know. You will need it every time you sign in.": "ଆପଣଙ୍କ ଡ୍ୟାସବୋର୍ଡ ଦୁଇ ପର୍ଯ୍ୟାୟରେ ସୁରକ୍ଷିତ: ଫୋନ୍ OTP ଓ କେବଳ ଆପଣ ଜାଣିଥିବା ପିନ୍। ପ୍ରତି ସାଇନ୍ ଇନ୍‌ରେ ଏହା ଦରକାର ହେବ।",
  "Your full name (HR / admin contact)": "ଆପଣଙ୍କ ପୂରା ନାମ (HR / ଆଡମିନ୍ ଯୋଗାଯୋଗ)",
  "Your name": "ଆପଣଙ୍କ ନାମ",
  "Your organisation’s public profile on Jeevia.": "Jeevia ରେ ଆପଣଙ୍କ ସଂସ୍ଥାର ସାର୍ବଜନୀନ ପ୍ରୋଫାଇଲ୍।",
  "Your role sees throughput, configuration and the audit trail — never symptoms, notes or reports. Every access by clinical staff is logged here.": "ଆପଣଙ୍କ ଭୂମିକା କାର୍ଯ୍ୟ, ବିନ୍ୟାସ ଓ ଅଡିଟ୍ ଦେଖେ — କେବେ ଲକ୍ଷଣ, ନୋଟ୍ କିମ୍ବା ରିପୋର୍ଟ ନୁହେଁ। କ୍ଲିନିକାଲ୍ କର୍ମଚାରୀଙ୍କ ପ୍ରତି ପ୍ରବେଶ ଏଠାରେ ଲେଖାହୁଏ।",
