  "Has a 12-lead ECG been recorded since arrival?": "ଆସିବା ପରେ 12-ଲିଡ୍ ECG କରାଯାଇଛି କି?",
  "Is the fever continuous or does it come with chills at a fixed time?": "ଜ୍ୱର ଲଗାତାର ନା ନିର୍ଦ୍ଦିଷ୍ଟ ସମୟରେ ଥରିବା ସହ ଆସେ?",
