  "Can the patient speak full sentences without pausing for breath?": "ରୋଗୀ ନିଶ୍ୱାସ ପାଇଁ ନ ଅଟକି ପୂରା ବାକ୍ୟ କହିପାରନ୍ତି କି?",
  "Any flashing lights, spots or blurred vision right now?": "ଏବେ କୌଣସି ଆଲୋକ ଝଲକା, ଦାଗ କିମ୍ବା ଝାପସା ଦେଖା?",
  "Has the cough lasted more than 2 weeks? Any blood in sputum?": "କାଶ 2 ସପ୍ତାହରୁ ଅଧିକ ହେଲାଣି କି? କଫରେ ରକ୍ତ?",
