  "How and when did the injury happen? Any loss of consciousness?": "ଆଘାତ କିପରି ଓ କେବେ ହେଲା? ଚେତା ହରାଇଥିଲେ କି?",
  "How many times has the child passed urine in the last 6 hours?": "ଗତ 6 ଘଣ୍ଟାରେ ଶିଶୁ କେତେଥର ପରିସ୍ରା କରିଛି?",
