  "Computer helpers": "କମ୍ପ୍ୟୁଟର ସହାୟକ",
  "Use AI helpers": "AI ସହାୟକ ବ୍ୟବହାର କରନ୍ତୁ",
  "Speech to text, translation and reading reports on this facility's computer. Your recorded words, and photos of handwritten papers, may also be read by a second engine online, in India (Sarvam AI).": "କଥାରୁ ଲେଖା, ଅନୁବାଦ ଓ ରିପୋର୍ଟ ପଢ଼ିବା ଏହି କେନ୍ଦ୍ରର କମ୍ପ୍ୟୁଟରରେ। ଆପଣଙ୍କ ରେକର୍ଡ ହୋଇଥିବା କଥା ଓ ହାତଲେଖା କାଗଜର ଫଟୋକୁ ଭାରତରେ ଥିବା ଆଉ ଏକ ଅନଲାଇନ୍ ସିଷ୍ଟମ୍ (Sarvam AI) ମଧ୍ୟ ପଢ଼ିପାରେ।",
  "Contains": "ଏଥିରେ ଅଛି",
  "Read online from handwriting by Sarvam Vision": "ହାତଲେଖା Sarvam Vision ଅନଲାଇନରେ ପଢ଼ିଲା",
  "Read by both offline and online engines": "ଅଫଲାଇନ ଓ ଅନଲାଇନ ଦୁଇଟି ପଢ଼ିଲା",
  "Read from a photo and matched to the Jan Aushadhi generic list or a list of Indian brands — confirm each one against the strip or prescription": "ଫଟୋରୁ ପଢ଼ି ଜନ ଔଷଧି ଜେନେରିକ ତାଲିକା ବା ଭାରତୀୟ ବ୍ରାଣ୍ଡ ତାଲିକା ସହ ମିଳାଯାଇଛି — ପ୍ରତ୍ୟେକକୁ ପତା ବା ପ୍ରେସକ୍ରିପସନ ସହ ମିଳାଇ ନିଶ୍ଚିତ କରନ୍ତୁ",
