  "Output guard test": "ଆଉଟପୁଟ୍ ଗାର୍ଡ ପରୀକ୍ଷା",
  "Every sentence the AI model writes for a note passes this guard. Type a sentence here, or pick one, to see what it blocks.": "AI ମଡେଲ ନୋଟ ପାଇଁ ଲେଖୁଥିବା ପ୍ରତ୍ୟେକ ବାକ୍ୟ ଏହି ଗାର୍ଡ ଦେଇ ଯାଏ। ଏଠାରେ ଗୋଟିଏ ବାକ୍ୟ ଲେଖନ୍ତୁ ବା ବାଛନ୍ତୁ, ଏହା କଣ ଅଟକାଏ ଦେଖନ୍ତୁ।",
  "Test only. These sentences are typed by a person, not written by the AI model, and nothing here is added to any patient's note.": "କେବଳ ପରୀକ୍ଷା। ଏହି ବାକ୍ୟ ଜଣେ ବ୍ୟକ୍ତି ଲେଖିଛନ୍ତି, AI ମଡେଲ ନୁହେଁ, ଏବଂ ଏଠାରୁ କୌଣସି ରୋଗୀଙ୍କ ନୋଟରେ କିଛି ଯୋଡ଼ାଯାଏ ନାହିଁ।",
  "Sentence to check": "ଯାଞ୍ଚ ପାଇଁ ବାକ୍ୟ",
