  "Optional. A phrase already in this data may be repeated, as in a real summary.": "ଇଚ୍ଛାଧୀନ। ଏହି ତଥ୍ୟରେ ଆଗରୁ ଥିବା ଶବ୍ଦ ଦୋହରାଯାଇପାରେ, ପ୍ରକୃତ ସାରାଂଶ ପରି।",
