  "e.g. Chronic check-in. Condition: diabetes.": "ଯେପରି: ପୁରୁଣା ରୋଗ ଯାଞ୍ଚ। ଅବସ୍ଥା: ମଧୁମେହ।",
  "Run guard test": "ଗାର୍ଡ ପରୀକ୍ଷା ଚଲାନ୍ତୁ",
