  "Blocked — this sentence would never reach a note": "ଅଟକାଗଲା — ଏହି ବାକ୍ୟ କେବେ ନୋଟରେ ପହଞ୍ଚିବ ନାହିଁ",
  "Test": "ପରୀକ୍ଷା",
  "In a real summary the whole AI text is dropped, the rules-based template note is used instead, and the rejected text is kept on the note for the reviewer.": "ପ୍ରକୃତ ସାରାଂଶରେ ପୂରା AI ଲେଖା ବାଦ ପଡ଼େ, ତା ବଦଳରେ ନିୟମ-ଆଧାରିତ ଟେମ୍ପଲେଟ ନୋଟ ବ୍ୟବହାର ହୁଏ, ଏବଂ ପ୍ରତ୍ୟାଖ୍ୟାତ ଲେଖା ସମୀକ୍ଷକଙ୍କ ପାଇଁ ନୋଟରେ ରଖାଯାଏ।",
  "Written to the audit log as a test.": "ଅଡିଟ୍ ଲଗରେ ପରୀକ୍ଷା ଭାବେ ଲେଖାଗଲା।",
  "Written to the audit log as GUARD_BLOCK, marked as a test.": "ଅଡିଟ୍ ଲଗରେ GUARD_BLOCK ଭାବେ ଲେଖାଗଲା, ପରୀକ୍ଷା ବୋଲି ଚିହ୍ନିତ।",
