  "Less urgent than the rules — the rules stand": "ନିୟମଠାରୁ କମ୍ ଜରୁରୀ — ନିୟମ ହିଁ ଲାଗୁ ରହିବ",
  "Reason hidden: it failed the safety checks": "କାରଣ ଲୁଚାଯାଇଛି: ଏହା ସୁରକ୍ଷା ଯାଞ୍ଚରେ ବିଫଳ ହେଲା",
  "AI model not available, so there is no second opinion.": "AI ମଡେଲ ଉପଲବ୍ଧ ନାହିଁ, ତେଣୁ କୌଣସି ଦ୍ୱିତୀୟ ମତ ନାହିଁ।",
  "The model's answer could not be read, so no opinion is shown.": "ମଡେଲର ଉତ୍ତର ପଢ଼ାଯାଇପାରିଲା ନାହିଁ, ତେଣୁ କୌଣସି ମତ ଦେଖାଯାଉନାହିଁ।",
  "Urgency comes only from the rules. Only a doctor can change it, with a written reason.": "ଜରୁରୀତା କେବଳ ନିୟମରୁ ଆସେ। କେବଳ ଡାକ୍ତର ଲିଖିତ କାରଣ ସହ ଏହାକୁ ବଦଳାଇପାରିବେ।",
  "AI second opinion is more urgent than the rules — take a second look": "AI ର ଦ୍ୱିତୀୟ ମତ ନିୟମଠାରୁ ଅଧିକ ଜରୁରୀ — ପୁଣି ଥରେ ଦେଖନ୍ତୁ",
  "AI second opinions": "AI ର ଦ୍ୱିତୀୟ ମତ",
  "The AI model's own urgency for each case, compared with the rules. It never changed any urgency: use this to review rules, not patients.": "ପ୍ରତ୍ୟେକ ମାମଲା ପାଇଁ AI ମଡେଲର ନିଜ ଜରୁରୀତା, ନିୟମ ସହ ତୁଳନା କରି। ଏହା କେବେ କୌଣସି ଜରୁରୀତା ବଦଳାଇନାହିଁ: ଏହାକୁ ନିୟମ ସମୀକ୍ଷା ପାଇଁ ବ୍ୟବହାର କରନ୍ତୁ, ରୋଗୀଙ୍କ ପାଇଁ ନୁହେଁ।",
  "Compared": "ତୁଳନା କରାଯାଇଛି",
