  "Agreed": "ସହମତ",
  "AI more urgent": "AI ଅଧିକ ଜରୁରୀ",
  "flagged for a second look": "ପୁଣି ଦେଖିବା ପାଇଁ ଚିହ୍ନିତ",
  "AI less urgent": "AI କମ୍ ଜରୁରୀ",
  "shown only; the rules stand": "କେବଳ ଦେଖାଯାଇଛି; ନିୟମ ହିଁ ଲାଗୁ",
  "No opinion for {n} case(s): model not available or answer unreadable.": "{n}ଟି ମାମଲାରେ କୌଣସି ମତ ନାହିଁ: ମଡେଲ ଉପଲବ୍ଧ ନାହିଁ କିମ୍ବା ଉତ୍ତର ପଢ଼ାଯାଇପାରିଲା ନାହିଁ।",
  "Rules vs AI model": "ନିୟମ ବନାମ AI ମଡେଲ",
  "Rows: the rules' urgency. Columns: the AI model's. The diagonal is agreement.": "ଧାଡ଼ି: ନିୟମର ଜରୁରୀତା। ସ୍ତମ୍ଭ: AI ମଡେଲର। କର୍ଣ୍ଣରେ ସହମତି।",
  "Cases where they differed": "ଯେଉଁ ମାମଲାରେ ଦୁହେଁ ଭିନ୍ନ ଥିଲେ",
  "Newest first. Final urgency is what the case ended with, after any doctor's override.": "ନୂଆଟି ପ୍ରଥମେ। ଶେଷ ଜରୁରୀତା ହେଉଛି ଡାକ୍ତରଙ୍କ କୌଣସି ପରିବର୍ତ୍ତନ ପରେ ମାମଲା ଯେଉଁଥିରେ ଶେଷ ହେଲା।",
  "Final": "ଶେଷ",
  "doctor override": "ଡାକ୍ତରଙ୍କ ଦ୍ୱାରା ବଦଳାଯାଇଛି",
  "No reason given": "କୌଣସି କାରଣ ଦିଆଯାଇନାହିଁ",
  "No disagreements in this period": "ଏହି ଅବଧିରେ କୌଣସି ଅସହମତି ନାହିଁ",
  "Model": "ମଡେଲ",
  "AI second opinions need the live API and the local model": "AI ର ଦ୍ୱିତୀୟ ମତ ପାଇଁ ଲାଇଭ API ଏବଂ ସ୍ଥାନୀୟ ମଡେଲ ଦରକାର",
  "A village fair or local deity's day that the state table does not have. Add its date for each year.": "ଗାଁ ମେଳା ବା ସ୍ଥାନୀୟ ଦେବତାଙ୍କ ଦିନ ଯାହା ରାଜ୍ୟ ତାଲିକାରେ ନାହିଁ। ପ୍ରତି ବର୍ଷର ତାରିଖ ଯୋଡ଼ନ୍ତୁ।",
  "About a year back and four months ahead. Festivals of local importance are in bold; every date has a source.": "ପ୍ରାୟ ଏକ ବର୍ଷ ପୂର୍ବରୁ ଚାରି ମାସ ପରେ ପର୍ଯ୍ୟନ୍ତ। ସ୍ଥାନୀୟ ଗୁରୁତ୍ୱର ପର୍ବ ମୋଟା ଅକ୍ଷରରେ; ପ୍ରତି ତାରିଖର ଉତ୍ସ ଦିଆଯାଇଛି।",
