  "Patients often date an illness by a festival or season. The note shows the date it points to beside their words, marked VAGUE; staff confirm it, and the rules never use it.": "ରୋଗୀମାନେ ପ୍ରାୟତଃ ରୋଗର ସମୟ କୌଣସି ପର୍ବ ବା ଋତୁ ଦ୍ୱାରା କହନ୍ତି। ନୋଟ ସେମାନଙ୍କ କଥା ପାଖରେ ସେହି ତାରିଖ ଦେଖାଏ, VAGUE (ଅସ୍ପଷ୍ଟ) ଚିହ୍ନ ସହ; କର୍ମଚାରୀ ଏହାକୁ ନିଶ୍ଚିତ କରନ୍ତି, ଏବଂ ନିୟମ ଏହାକୁ କେବେ ବ୍ୟବହାର କରେ ନାହିଁ।",
