  "RED rules not yet ruled out": "RED ନିୟମ ଏପର୍ଯ୍ୟନ୍ତ ବାଦ ପଡ଼ିନାହିଁ",
  "Rains begin": "ବର୍ଷା ଆରମ୍ଭ",
  "Read": "ପଢ଼ନ୍ତୁ",
