  "Regional calendar saved — new notes use it": "ଆଞ୍ଚଳିକ କ୍ୟାଲେଣ୍ଡର ସଞ୍ଚୟ ହେଲା — ନୂଆ ନୋଟ ଏହାକୁ ବ୍ୟବହାର କରିବ",
