  "The regional calendar needs the live API": "ଆଞ୍ଚଳିକ କ୍ୟାଲେଣ୍ଡର ପାଇଁ ଲାଇଭ API ଦରକାର",
  "The titles staff use here. They appear on screens, staff roles and the helper list at the kiosk.": "ଏଠାରେ କର୍ମଚାରୀ ବ୍ୟବହାର କରୁଥିବା ପଦବୀ। ଏଗୁଡ଼ିକ ସ୍କ୍ରିନ, କର୍ମଚାରୀ ଭୂମିକା ଓ କିଓସ୍କର ସହାୟକ ତାଲିକାରେ ଦେଖାଯାଏ।",
  "This facility's own festivals": "ଏହି କେନ୍ଦ୍ରର ନିଜ ପର୍ବ",
  "This facility's state is not in the regional table, so national festivals are used and monsoon dates are unknown. Set the state in Facility setup.": "ଏହି କେନ୍ଦ୍ରର ରାଜ୍ୟ ଆଞ୍ଚଳିକ ତାଲିକାରେ ନାହିଁ, ତେଣୁ ଜାତୀୟ ପର୍ବ ବ୍ୟବହାର ହୁଏ ଏବଂ ମୌସୁମୀ ତାରିଖ ଅଜଣା। କେନ୍ଦ୍ର ସେଟଅପରେ ରାଜ୍ୟ ସେଟ କରନ୍ତୁ।",
  "This state also gets the northeast monsoon (20 Oct – 31 Dec). “The rains” shows both and asks which.": "ଏହି ରାଜ୍ୟରେ ଉତ୍ତର-ପୂର୍ବ ମୌସୁମୀ (20 ଅକ୍ଟୋବର – 31 ଡିସେମ୍ବର) ମଧ୍ୟ ଆସେ। “ବର୍ଷା” କହିଲେ ଦୁଇଟି ଦେଖାଏ ଓ କେଉଁଟି ପଚାରେ।",
