  "Used only to count fevers per hostel, so the campus doctor can spot an outbreak. Your name is never shown with it.": "ଏହା କେବଳ ପ୍ରତି ହଷ୍ଟେଲରେ ଜ୍ୱର ଗଣିବା ପାଇଁ ବ୍ୟବହାର ହୁଏ, ଯାହାଦ୍ୱାରା କ୍ୟାମ୍ପସ୍ ଡାକ୍ତର ରୋଗ ବିସ୍ତାର ଜାଣିପାରିବେ। ଏହା ସହିତ ଆପଣଙ୍କ ନାମ କେବେ ଦେଖାଯାଏ ନାହିଁ।",
  "Work and exposure": "କାମ ଏବଂ ସଂସ୍ପର୍ଶ",
  "For the workplace health check. Your employer never sees these answers or any symptom, only department totals.": "କାର୍ଯ୍ୟସ୍ଥଳ ସ୍ୱାସ୍ଥ୍ୟ ପରୀକ୍ଷା ପାଇଁ। ଆପଣଙ୍କ ନିଯୁକ୍ତିଦାତା ଏହି ଉତ୍ତର କିମ୍ବା କୌଣସି ଲକ୍ଷଣ କେବେ ଦେଖନ୍ତି ନାହିଁ, କେବଳ ବିଭାଗର ମୋଟ ସଂଖ୍ୟା।",
  "At work, are you exposed to": "କାମରେ ଆପଣ କ'ଣ ଏଗୁଡ଼ିକ ସଂସ୍ପର୍ଶରେ ଆସନ୍ତି",
  "Silica / stone dust": "ସିଲିକା / ପଥର ଧୂଳି",
  "Coal dust": "କୋଇଲା ଧୂଳି",
  "Cotton dust": "କପା ଧୂଳି",
  "Asbestos": "ଆସବେଷ୍ଟସ୍",
  "Other dust": "ଅନ୍ୟ ଧୂଳି",
  "Loud noise": "ଜୋର ଶବ୍ଦ",
  "Chemicals or fumes": "ରାସାୟନିକ କିମ୍ବା ଧୂଆଁ",
  "Pesticides": "କୀଟନାଶକ",
  "Heat": "ଗରମ",
  "Years in this work": "ଏହି କାମରେ କେତେ ବର୍ଷ",
  "Weeks of cough": "କେତେ ସପ୍ତାହ ହେଲା କାଶ",
  "(0 if no cough)": "(କାଶ ନ ଥିଲେ 0)",
  "Breathing compared with the last workplace check": "ଗତ କାର୍ଯ୍ୟସ୍ଥଳ ପରୀକ୍ଷା ତୁଳନାରେ ନିଶ୍ୱାସ",
  "Same": "ସେହିପରି",
  "First check": "ପ୍ରଥମ ପରୀକ୍ଷା",
  "Mask, ear plugs or gloves given?": "ମାସ୍କ, କାନ ପ୍ଲଗ୍ କିମ୍ବା ଗ୍ଲୋଭସ୍ ଦିଆଯାଇଛି କି?",
  "Worn during work": "କାମ ସମୟରେ ପିନ୍ଧନ୍ତି",
  "Always": "ସବୁବେଳେ",
  "Sometimes": "ବେଳେବେଳେ",
  "Never": "କେବେ ନୁହେଁ",
  "Health worker": "ସ୍ୱାସ୍ଥ୍ୟ କର୍ମୀ",
  "Health worker / ASHA": "ସ୍ୱାସ୍ଥ୍ୟ କର୍ମୀ / ଆଶା",
  "Maternal follow-ups": "ମାତୃ ଫଲୋ-ଅପ୍",
  "Missed check-up": "ପରୀକ୍ଷା ଛୁଟିଗଲା",
  "Reminder call due": "ମନେ ପକାଇବା କଲ୍ ବାକି",
  "Reached — waiting for her visit": "ଯୋଗାଯୋଗ ହେଲା — ତାଙ୍କ ଆସିବା ଅପେକ୍ଷା",
  "Scheduled": "ସ୍ଥିର",
  "She came": "ସେ ଆସିଲେ",
  "Reached her": "ତାଙ୍କ ସହ ଯୋଗାଯୋଗ ହେଲା",
  "Could not reach": "ଯୋଗାଯୋଗ ହୋଇପାରିଲା ନାହିଁ",
  "Place reminder call": "ମନେ ପକାଇବା କଲ୍ କରନ୍ତୁ",
